const rows = items[0].json.data ? [items[0].json] : items;
if (!rows.length || !rows[0].data) {
  return [{ json: { sessionState: {} } }];
}
return [{ json: { sessionState: rows[0].data } }];

// Expects original sessionState in $json.sessionState and patch in $json.patch
const orig = $json.sessionState || {};
const patch = $json.patch || {};
const next = { ...orig };
for (const [k,v] of Object.entries(patch)) {
  if (v === null) { delete next[k]; } else { next[k] = v; }
}
return [{ json: { userId: $json.userId, merged: next } }];
